 function prose(value){if(typeof value!=='string')return value;let s=value;for(const [from,to]of replacements)s=s.split(from).join(to);
  // These specific sentence openings are editorial abbreviations, not formula labels.
  s=s.replace(/(^|\. )(No [^.?!]+)(\.)(?= |$)/g,(all,prefix,clause,end)=>{const nouns=clause.slice(3);if(/\b(is|are|was|were|has|have|would|should|can|need|means|qualifies|applies|requires|occurs|remains|will|must)\b/i.test(nouns))return all;return prefix+'The example excludes '+nouns.charAt(0).toLowerCase()+nouns.slice(1)+end;});
  s=s.replace(/(^|\. )Omits /g,'$1The example omits ').replace(/(^|\. )Excludes /g,'$1The example excludes ');
  return s;
 }
 window.MODULE_PROSE=prose;
