 function strings(value){if(typeof value==='string')return prose(value);if(Array.isArray(value))return value.map(strings);if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([k,v])=>[k,strings(v)]));return value;}
 for(const l of window[keys[module]]||[]){for(const key of ['intro','simple','scope','key','challenge','notes'])if(l[key])l[key]=strings(l[key]);const calculate=l.compute;l.compute=function(...args){const r=calculate.apply(this,args);return {...r,explanation:prose(r.explanation),...(r.note?{note:prose(r.note)}:{}),...(r.key?{key:prose(r.key)}:{})};};}
